        public Input<bool>? Muted { get; set; }

        /// <summary>
        /// The name of the monitor.
        /// </summary>
        [Input("name")]
        public Input<string>? Name { get; set; }

        [Input("privateLocations")]
        private InputList<string>? _privateLocations;

        /// <summary>
        /// The slugs of the private locations to run the monitor from.
        /// </summary>
        public InputList<string> PrivateLocations
        {
            get => _privateLocations ?? (_privateLocations = new InputList<string>());
            set => _privateLocations = value;
        }

        /// <summary>
        /// The parameters for the SSL connection.
        /// </summary>
        [Input("request")]
        public Input<Inputs.SslMonitorRequestGetArgs>? Request { get; set; }

        /// <summary>
        /// A strategy for retrying failed check/monitor runs.
        /// </summary>
        [Input("retryStrategy")]
        public Input<Inputs.SslMonitorRetryStrategyGetArgs>? RetryStrategy { get; set; }

        /// <summary>
        /// Determines whether the monitor runs in all its locations in parallel instead of in one location at a time, round-robin. Defaults to `False`.
        /// </summary>
        [Input("runParallel")]
        public Input<bool>? RunParallel { get; set; }

        /// <summary>
        /// The ID of the runtime to use for the monitor.
        /// </summary>
        [Input("runtimeId")]
        public Input<string>? RuntimeId { get; set; }

        [Input("tags")]
        private InputList<string>? _tags;

        /// <summary>
        /// Tags for organizing and filtering checks and monitors.
        /// </summary>
        public InputList<string> Tags
        {
            get => _tags ?? (_tags = new InputList<string>());
            set => _tags = value;
        }

        /// <summary>
        /// Create and resolve an incident based on the alert configuration. Useful for status page automation.
        /// </summary>
        [Input("triggerIncident")]
        public Input<Inputs.SslMonitorTriggerIncidentGetArgs>? TriggerIncident { get; set; }

        /// <summary>
        /// When true, the account level alert settings are used instead of the `AlertSettings` of this monitor. Defaults to `True` when `AlertSettings` is not set, and to `False` when it is.
        /// </summary>
        [Input("useGlobalAlertSettings")]
        public Input<bool>? UseGlobalAlertSettings { get; set; }

        public SslMonitorState()
        {
        }
        public static new SslMonitorState Empty => new SslMonitorState();
    }
}
